with a as(select * from public.authors where open_library_id=any(array['OL27363A','OL10779545A','OL656011A','OL74469A','OL22242A','OL1970832A','OL14498384A','OL57758A','OL153884A','OL253800A','OL187319A','OL63616A']::text[]) or id=any(array[35,33,654,700,2882,905,912]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'authors',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from a t),'author_corpora',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where author_id in(select id from a)),'isbn_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.editions t where regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789029000475','9789061691839','9789029517348','9789027491732','9789020232523','9789029519847','9789025401023','9789072810014','9789074336321','9789029583916']::text[])),'source_work_matches',(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from public.works t where open_library_id=any(array['OL274509W','OL3738761W','OL857189W','OL166923W','OL8051539W','OL719939W','OL1456888W','OL14936448W','OL1667589W','OL34858547W']::text[])),'title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','works','row',to_jsonb(t))),'[]') from public.works t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['elcoronelnotienequienleescriba','dekolonelkrijgtnooitpost','84charingcrossroad','charingcrossroad84','effibriest','despeler','thegambler','igrok','erinnerungenandiezukunft','warendegodenkosmonauten','deunster','overlichtendedrempels','depijp','wantditismijnlichaam','hetgeuzenboek']::text[])),'edition_title_matches',(select coalesce(jsonb_agg(jsonb_build_object('relation','editions','row',to_jsonb(t))),'[]') from public.editions t where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['elcoronelnotienequienleescriba','dekolonelkrijgtnooitpost','84charingcrossroad','charingcrossroad84','effibriest','despeler','thegambler','igrok','erinnerungenandiezukunft','warendegodenkosmonauten','deunster','overlichtendedrempels','depijp','wantditismijnlichaam','hetgeuzenboek']::text[])),'reserved_test_ranges',jsonb_build_object('works',(select count(*) from public.works where id between 987112001 and 987112999),'editions',(select count(*) from public.editions where id between 987212001 and 987212999),'authors',(select count(*) from public.authors where id between 987312001 and 987312999))) as preflight;
